after:
let sweep = profileSweeps.get(profileDirectory);
if (!sweep) {
  sweep = yield* Effect.cached(
    Effect.forEach(
      new Set([directories.runtimeTemp, path.join(profileDirectory, "antigravity-acp", "tmp")]),
      directory => removeAntigravityRuntimeTempDirs(directory),
      { discard: true },
    ).pipe(Effect.provideService(FileSystem.FileSystem, fileSystem), Effect.uninterruptible),

