      ? Effect.fail(new ProviderSetupError({
          instanceId, operation: "start",
          detail: "Select the Antigravity sign-in method in provider settings before connecting.",
        }))
      : authFlow.controller.start(owner, stopSessions),
  subscribe: owner => authFlow.controller.subscribe(owner).pipe(Stream.map(state => ({
    ...state,
    methods: [{
